-- Set programs that you use
local terminal    = "kitty"
local fileManager = "nautilus"
local menu = "$HOME/.config/rofi/scripts/launcher.sh"
local browser     = "google-chrome-stable"
local mailClient  = "betterbird"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function ()
    -- A random wallpaper per monitor, kept until the next login
    hl.exec_cmd("$HOME/.config/hypr/scripts/random-wallpaper.sh")
    -- Clipboard history (text and images) for the clipboard menu
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    -- Status bar on every monitor
    hl.exec_cmd("waybar")
    -- Locks the screen when logind asks (lid closed, before suspend)
    hl.exec_cmd("hypridle")
    -- Admin password window for pkexec/GUI apps (its unit waits for graphical-session.target, which this session never reaches)
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
end)


