-- Show desktop: jump to an empty workspace on this monitor; again: back to where you were
hl.bind(mainMod .. " + D", function()
    local ws = hl.get_active_workspace()
    if ws ~= nil and ws.windows == 0 then
        hl.dispatch(hl.dsp.focus({ workspace = "previous" }))
    else
        hl.dispatch(hl.dsp.focus({ workspace = "emptym" }))
    end
end, { description = "Show desktop (empty workspace, again: back)" })

-- Magnifier: zoom around the cursor (hold to keep zooming)
local function zoom(step)
    local z = hl.get_config("cursor.zoom_factor") + step
    hl.config({ cursor = { zoom_factor = math.max(1, math.min(z, 5)) } })
end
hl.bind(mainMod .. " + EQUAL", function() zoom(0.5) end,  { repeating = true, description = "Zoom in (magnifier)" })
hl.bind(mainMod .. " + MINUS", function() zoom(-0.5) end, { repeating = true, description = "Zoom out (magnifier)" })
hl.bind(mainMod .. " + SHIFT + MINUS", function() hl.config({ cursor = { zoom_factor = 1 } }) end, { description = "Reset zoom (magnifier)" })
