-- No gaps, borders or rounding (Super+Shift+F) and focus mode = that + no Waybar (Super+Alt+F). Press again to restore.
local savedGaps = nil      -- original gaps, border size and rounding while they are hidden
local barHidden = false
local function setGaps(hide)
    if hide and savedGaps == nil then
        savedGaps = { inner = hl.get_config("general.gaps_in"), outer = hl.get_config("general.gaps_out"), border = hl.get_config("general.border_size"), rounding = hl.get_config("decoration.rounding") }
        hl.config({ general = { gaps_in = 0, border_size = 0 }, decoration = { rounding = 0 } })
    elseif not hide and savedGaps ~= nil then
        hl.config({ general = { gaps_in = savedGaps.inner, gaps_out = savedGaps.outer, border_size = savedGaps.border }, decoration = { rounding = savedGaps.rounding } })
        savedGaps = nil
    end
end
local function setBar(hide)
    if hide ~= barHidden then
        barHidden = hide
        hl.exec_cmd("pkill -SIGUSR1 -x waybar")    -- SIGUSR1 toggles Waybar visibility
    end
end
-- Without gaps, keep a small space between Waybar and the windows (none when the bar is hidden)
local function setTopGap()
    if savedGaps ~= nil then
        hl.config({ general = { gaps_out = { top = barHidden and 0 or 4, right = 0, bottom = 0, left = 0 } } })
    end
end
hl.bind(mainMod .. " + SHIFT + F", function()
    setGaps(savedGaps == nil)
    setTopGap()
end, { description = "Toggle gaps, borders and rounding" })
hl.bind(mainMod .. " + ALT + F", function()
    local on = not (barHidden and savedGaps ~= nil)
    setGaps(on)
    setBar(on)
    setTopGap()
end, { description = "Toggle focus mode (no bar, gaps, borders or rounding)" })

-- Pop out: floating, pinned on every workspace, centered. Press again to put it back.
hl.bind(mainMod .. " + SHIFT + V", function()
    local w = hl.get_active_window()
    if w == nil then return end
    if w.floating and w.pinned then
        hl.dispatch(hl.dsp.window.pin({ action = "unset" }))
        hl.dispatch(hl.dsp.window.float({ action = "unset" }))
    else
        hl.dispatch(hl.dsp.window.float({ action = "set" }))
        hl.dispatch(hl.dsp.window.resize({ x = 1100, y = 700 }))
        hl.dispatch(hl.dsp.window.center())
        hl.dispatch(hl.dsp.window.pin({ action = "set" }))
    end
end, { description = "Toggle pop-out window (floating, pinned)" })

