-- Arrows: Shift moves the window, Alt resizes it, Shift + Alt moves the whole workspace to the monitor that way
local arrows = {
    { key = "left",  monitor = "l", x = -50, y = 0 },
    { key = "right", monitor = "r", x = 50,  y = 0 },
    { key = "up",    monitor = "u", x = 0,   y = -50 },
    { key = "down",  monitor = "d", x = 0,   y = 50 },
}
for _, a in ipairs(arrows) do
    hl.bind(mainMod .. " + SHIFT + " .. a.key, hl.dsp.window.move({ direction = a.key }), { description = "Move window " .. a.key })
end
for _, a in ipairs(arrows) do
    hl.bind(mainMod .. " + ALT + " .. a.key, hl.dsp.window.resize({ x = a.x, y = a.y, relative = true }), { repeating = true, description = "Resize window " .. a.key })
end
for _, a in ipairs(arrows) do
    hl.bind(mainMod .. " + SHIFT + ALT + " .. a.key, hl.dsp.workspace.move({ monitor = a.monitor }), { description = "Move workspace to monitor " .. a.key })
end

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9] (+ ALT: stay on the current workspace)
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}), { description = "Go to workspace " .. i })
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }), { description = "Move window to workspace " .. i })
    hl.bind(mainMod .. " + SHIFT + ALT + " .. key, hl.dsp.window.move({ workspace = i, follow = false }), { description = "Move window silently to workspace " .. i })
end

