-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true, description = "Next track" })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play/pause media" })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play/pause media" })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true, description = "Previous track" })
hl.bind("XF86AudioStop",  hl.dsp.exec_cmd("playerctl stop"),       { locked = true, description = "Stop media" })

-- Extra keys found on some keyboards
hl.bind("XF86Calculator",        hl.dsp.exec_cmd("gnome-calculator"),            { description = "Calculator key" })
hl.bind("XF86Mail",              hl.dsp.exec_cmd(mailClient),                    { description = "Mail key (email)" })
hl.bind("XF86HomePage",          hl.dsp.exec_cmd(browser),                       { description = "Home page key (browser)" })
hl.bind("XF86WWW",               hl.dsp.exec_cmd(browser),                       { description = "WWW key (browser)" })
hl.bind("XF86Search",            hl.dsp.exec_cmd(menu),                          { description = "Search key (launcher)" })
hl.bind("XF86Explorer",          hl.dsp.exec_cmd(fileManager),                   { description = "Explorer key (file manager)" })
hl.bind("XF86MyComputer",        hl.dsp.exec_cmd(fileManager),                   { description = "My Computer key (file manager)" })
hl.bind("XF86ScreenSaver",       hl.dsp.exec_cmd("loginctl lock-session"),       { description = "Lock key (lock screen)" })
hl.bind("XF86Bluetooth",         hl.dsp.exec_cmd("kitty --class popup -e bluetui"), { description = "Bluetooth key (bluetooth settings)" })
hl.bind("XF86KbdBrightnessUp",   hl.dsp.exec_cmd("brightnessctl -d '*kbd_backlight' set 10%+"), { locked = true, repeating = true, description = "Keyboard brightness up" })
hl.bind("XF86KbdBrightnessDown", hl.dsp.exec_cmd("brightnessctl -d '*kbd_backlight' set 10%-"), { locked = true, repeating = true, description = "Keyboard brightness down" })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Blur whatever is behind rofi (its themes use translucent backgrounds)
hl.layer_rule({
    name         = "rofi-blur",
    match        = { namespace = "^rofi$" },
    blur         = true,
    ignore_alpha = 0,
})

hl.layer_rule({
    name         = "waybar-blur",
    match        = { namespace = "^waybar$" },
    blur         = true,
    -- Blur only the pills, not the transparent gaps between them
    ignore_alpha = 0.1,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Apps opened from the Waybar pills (impala, bluetui, yay, pavucontrol) float centered
-- like a popup instead of resizing the tiled windows. Kitty ones use --class popup.
hl.window_rule({
    name  = "waybar-popups",
    match = { class = "^(popup|org\\.pulseaudio\\.pavucontrol)$" },

    float  = true,
    size   = "1000 640",
    center = true,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
